import { Invoice } from "./types";
import { format } from "date-fns";

const RFC_LOGO_PNG = "";

export function generateInvoiceHTML(invoice: Invoice): string {
  const isAdmission = invoice.period === "admission";
  const periodLabel = isAdmission
    ? "Admission"
    : format(new Date(invoice.period + "-01"), "MMMM yyyy");
  const paidDate = invoice.paid_at
    ? format(new Date(invoice.paid_at), "dd MMM yyyy, hh:mm a")
    : "\u2014";
  const createdDate = format(new Date(invoice.created_at), "dd MMM yyyy");

  return `
<!DOCTYPE html>
<html>
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1" />
  <style>
    * { margin: 0; padding: 0; box-sizing: border-box; }

    body {
      font-family: 'Helvetica Neue', Helvetica, Arial, sans-serif;
      padding: 0;
      color: #1a1a1a;
      background: #fff;
    }

    .page {
      position: relative;
      padding: 40px 36px 36px;
      min-height: 100vh;
    }

    /* Watermark logo behind content */
    .watermark {
      position: fixed;
      top: 50%;
      left: 50%;
      transform: translate(-50%, -50%);
      opacity: 0.03;
      z-index: 0;
      pointer-events: none;
    }
    .watermark img {
      width: 280px;
      height: 280px;
      border-radius: 50%;
      border: none !important;
      outline: none !important;
      box-shadow: none !important;
      background: transparent !important;
    }

    .content {
      position: relative;
      z-index: 1;
    }

    /* Green accent bar at top */
    .accent-bar {
      height: 5px;
      background: linear-gradient(90deg, #0d3311, #1b5e20, #2e7d32, #43a047);
      margin-bottom: 28px;
    }

    /* Header */
    .header-table {
      width: 100%;
      margin-bottom: 24px;
    }
    .header-table td {
      vertical-align: middle;
    }
    .logo-cell {
      width: 68px;
      padding-right: 16px;
    }
    .logo-wrap {
      width: 64px;
      height: 64px;
      border-radius: 50%;
      border: 3px solid #1b5e20;
      overflow: hidden;
      background: #fff;
    }
    .logo-wrap img {
      width: 100%;
      height: 100%;
      object-fit: cover;
      object-position: center top;
      display: block;
      border: none;
    }
    .club-title {
      font-size: 24px;
      font-weight: 800;
      color: #1b5e20;
      letter-spacing: 0.3px;
      line-height: 1.2;
    }
    .estd {
      font-size: 12px;
      color: #888;
      font-weight: 500;
      letter-spacing: 1px;
    }
    .receipt-label {
      font-size: 13px;
      color: #2e7d32;
      font-weight: 700;
      margin-top: 3px;
      text-transform: uppercase;
      letter-spacing: 2px;
    }

    /* Invoice number bar */
    .invoice-bar {
      background: linear-gradient(135deg, #1b5e20, #2e7d32);
      color: white;
      padding: 12px 20px;
      border-radius: 8px;
      margin-bottom: 24px;
    }
    .invoice-bar table {
      width: 100%;
    }
    .invoice-bar td {
      color: white;
    }
    .inv-no {
      font-size: 15px;
      font-weight: 700;
      letter-spacing: 1px;
    }
    .inv-date {
      font-size: 13px;
      font-weight: 500;
      text-align: right;
      opacity: 0.9;
    }

    /* Details */
    .details-table {
      width: 100%;
      margin-bottom: 24px;
      border-spacing: 12px 0;
    }
    .detail-card {
      background: #f8faf8;
      border-radius: 8px;
      padding: 14px 18px;
      border-left: 4px solid #1b5e20;
      vertical-align: top;
      width: 50%;
    }
    .detail-card h3 {
      font-size: 10px;
      text-transform: uppercase;
      letter-spacing: 1.5px;
      color: #888;
      font-weight: 600;
      margin-bottom: 6px;
    }
    .detail-card p {
      font-size: 15px;
      font-weight: 600;
      color: #1a1a1a;
      margin-bottom: 2px;
      line-height: 1.5;
    }
    .detail-card .sub {
      font-size: 12px;
      font-weight: 400;
      color: #666;
    }

    /* Amount section */
    .amount-section {
      background: linear-gradient(135deg, #e8f5e9, #c8e6c9);
      border-radius: 10px;
      padding: 20px;
      margin-bottom: 20px;
      border: 1px solid #a5d6a7;
    }
    .amount-table {
      width: 100%;
    }
    .amount-table td {
      padding: 6px 0;
    }
    .amount-label {
      font-size: 14px;
      color: #333;
      font-weight: 500;
    }
    .amount-value {
      font-size: 14px;
      color: #1a1a1a;
      font-weight: 600;
      text-align: right;
    }
    .total-row td {
      border-top: 2px solid #1b5e20;
      padding-top: 14px;
    }
    .total-label {
      font-size: 17px;
      font-weight: 700;
      color: #1b5e20;
    }
    .total-value {
      font-size: 26px;
      font-weight: 800;
      color: #1b5e20;
      text-align: right;
    }

    /* Payment info */
    .payment-table {
      width: 100%;
      margin-bottom: 20px;
      border-spacing: 12px 0;
    }
    .payment-chip {
      background: #f0f0f0;
      padding: 10px 16px;
      border-radius: 8px;
      font-size: 13px;
      font-weight: 500;
    }
    .payment-chip strong {
      color: #1b5e20;
    }

    /* Paid stamp */
    .paid-stamp {
      text-align: center;
      margin: 16px 0;
      padding: 10px;
      border: 3px solid #2e7d32;
      border-radius: 10px;
    }
    .paid-stamp-text {
      font-size: 22px;
      font-weight: 800;
      color: #2e7d32;
      letter-spacing: 8px;
      text-transform: uppercase;
    }

    /* Divider */
    .divider {
      height: 1px;
      background: linear-gradient(90deg, transparent, #ccc, transparent);
      margin: 20px 0;
    }

    /* Footer */
    .footer {
      text-align: center;
      padding-top: 12px;
    }
    .footer-club {
      font-size: 12px;
      font-weight: 700;
      color: #1b5e20;
      letter-spacing: 1px;
      margin-bottom: 4px;
    }
    .footer-note {
      font-size: 10px;
      color: #999;
      line-height: 1.6;
    }
  </style>
</head>
<body>
  <div class="page">
    <!-- Watermark logo -->
    <div class="watermark">
      <img src="data:image/png;base64,${RFC_LOGO_PNG}" alt="" />
    </div>

    <div class="content">
      <!-- Green accent bar -->
      <div class="accent-bar"></div>

      <!-- Header with logo -->
      <table class="header-table" cellpadding="0" cellspacing="0">
        <tr>
          <td class="logo-cell">
            <div class="logo-wrap">
              <img src="data:image/png;base64,${RFC_LOGO_PNG}" alt="RFC" />
            </div>
          </td>
          <td>
            <div class="club-title">Ranaghat Friends Club</div>
            <div class="estd">ESTD. 1968</div>
            <div class="receipt-label">Fee Receipt</div>
          </td>
        </tr>
      </table>

      <!-- Invoice number bar -->
      <div class="invoice-bar">
        <table cellpadding="0" cellspacing="0">
          <tr>
            <td class="inv-no">#${invoice.id.slice(0, 8).toUpperCase()}</td>
            <td class="inv-date">${createdDate}</td>
          </tr>
        </table>
      </div>

      <!-- Details -->
      <table class="details-table" cellpadding="0" cellspacing="0">
        <tr>
          <td class="detail-card">
            <h3>Student</h3>
            <p>${invoice.student_name}</p>
          </td>
          <td style="width: 12px;"></td>
          <td class="detail-card">
            <h3>Guardian</h3>
            <p>${invoice.guardian_name}</p>
            <p class="sub">${invoice.guardian_phone}</p>
          </td>
        </tr>
      </table>

      <!-- Amount -->
      <div class="amount-section">
        <table class="amount-table" cellpadding="0" cellspacing="0">
          <tr>
            <td class="amount-label">Description</td>
            <td class="amount-value">${invoice.description || "Monthly Fee"} \u2014 ${periodLabel}</td>
          </tr>
          <tr class="total-row">
            <td class="total-label">Total Amount</td>
            <td class="total-value">&#8377;${invoice.amount.toLocaleString("en-IN")}</td>
          </tr>
        </table>
      </div>

      ${invoice.status === "paid" ? `
      <!-- Payment info -->
      <table class="payment-table" cellpadding="0" cellspacing="0">
        <tr>
          <td class="payment-chip"><strong>Method:</strong> ${invoice.payment_method || "\u2014"}</td>
          <td style="width: 12px;"></td>
          <td class="payment-chip"><strong>Paid On:</strong> ${paidDate}</td>
        </tr>
      </table>

      <!-- Paid stamp -->
      <div class="paid-stamp">
        <span class="paid-stamp-text">&#10003; PAID</span>
      </div>
      ` : ""}

      <!-- Footer -->
      <div class="divider"></div>
      <div class="footer">
        <div class="footer-club">Ranaghat Friends Club &bull; Estd. 1968</div>
        <div class="footer-note">This is a computer-generated receipt and does not require a signature.</div>
      </div>
    </div>
  </div>
</body>
</html>`;
}
